    width > 0 ? UPGRADE_SCREEN.preview.width / width : 1,
    height > 0 ? UPGRADE_SCREEN.preview.height / height : 1,
  );
  return {
    scale,
    x: displayPixel(-(x + width / 2) * scale),
    y: displayPixel(-(y + height / 2) * scale),
    width: width * scale,
    height: height * scale,
  };
}
